import type { ReactNode } from "react";
import Link from "next/link";
import { legalConfig as c } from "./legal-config";

export type LegalSlug =
  | "terms"
  | "privacy"
  | "cookies"
  | "acceptable-use"
  | "marketplace-terms"
  | "publisher-terms"
  | "data-processing-addendum"
  | "subprocessors"
  | "vulnerability-disclosure"
  | "refunds"
  | "accessibility"
  | "complaints";

export type LegalDocument = {
  slug: LegalSlug;
  title: string;
  shortTitle: string;
  summary: string;
  audience: string;
  sections: Array<{ id: string; title: string; content: ReactNode }>;
};

const External = ({ href, children }: { href: string; children: ReactNode }) => (
  <a href={href} rel="noreferrer">{children}</a>
);
const Contact = ({ kind = "legal" }: { kind?: "legal" | "privacy" | "accessibility" | "security" }) => {
  const address = kind === "privacy" ? c.privacyEmail : kind === "accessibility" ? c.accessibilityEmail : kind === "security" ? c.securityEmail : c.legalEmail;
  const email = address.startsWith("[REQUIRED") ? <span className="legal-required">{address}</span> : <a href={`mailto:${address}`}>{address}</a>;
  return <>{email} or our <Link href={`/contact?type=${kind}`}>contact form</Link></>;
};

const identity = <>
  <p>The service is operated under the trading name <strong>{c.tradingName}</strong> by <span className="legal-required">{c.legalName}</span>, registered as <span className="legal-required">{c.companyNumber}</span>. Registered office: <span className="legal-required">{c.registeredOffice}</span>. VAT number: <span className="legal-required">{c.vatNumber}</span>.</p>
  <p>In these documents, “sndbox”, “we”, “us” and “our” mean that legal entity.</p>
</>;

const consumerSavings = <p>If you are a consumer, nothing in these terms excludes or limits rights or remedies that cannot lawfully be excluded. This includes rights under the UK <External href="https://www.legislation.gov.uk/ukpga/2015/15/contents">Consumer Rights Act 2015</External> and <External href="https://www.legislation.gov.uk/uksi/2013/3134/contents">Consumer Contracts Regulations 2013</External>, or Ireland’s <External href="https://www.irishstatutebook.ie/eli/2022/act/37/enacted/en/html">Consumer Rights Act 2022</External>, as applicable.</p>;

const terms: LegalDocument = {
  slug: "terms", shortTitle: "Terms", title: "Terms of service",
  summary: "The contract for using sndbox websites, desktop software, cloud execution, accounts and paid plans.",
  audience: "Everyone who accesses or uses sndbox",
  sections: [
    { id:"operator", title:"1. Who we are", content:identity },
    { id:"agreement", title:"2. How this agreement works", content:<><p>These Terms, the documents they link to, the order or checkout shown to you, and any signed order form form the agreement between you and sndbox. If a signed order form conflicts with these Terms, the order form controls for that conflict. Our <Link href="/legal/privacy">Privacy notice</Link> describes personal-data processing and is not a contractual term except where the law says otherwise.</p><p>By creating an account, downloading or using the service, or placing an order, you agree to this agreement. If you use sndbox for an organisation, you confirm you have authority to bind it. Consumers contract in their personal capacity and retain the statutory protections described below.</p></> },
    { id:"definitions", title:"Key definitions", content:<><p><strong>Account</strong> means a personal sndbox identity. <strong>Workspace</strong> means a shared or personal service area. <strong>Authorised User</strong> means a person the customer permits to use its Workspace. <strong>Customer Content</strong> means data, workflows, files, prompts, credentials, instructions and outputs supplied or generated under the customer’s direction. <strong>Documentation</strong> means the current user and technical documentation we publish. <strong>Hosted Service</strong> means functionality run on infrastructure arranged by sndbox. <strong>Local Service</strong> means software run on the user’s device or self-hosted runner. <strong>Plugin</strong> means an extension distributed through or used with sndbox. <strong>Order</strong> means an accepted checkout, order form or other purchase record.</p><p>“Including” does not limit the words before it. A reference to law includes amendments and replacements. Headings aid navigation but do not alter meaning. If translated terms conflict, the English version controls except where mandatory law requires otherwise.</p></> },
    { id:"eligibility", title:"3. Eligibility and accounts", content:<><p>You must be at least 18 and legally capable of entering a contract. Keep credentials secure, use accurate account information, and promptly tell us of suspected compromise. You are responsible for activity by people you authorise and for configuring workspace roles, approvals and runners appropriately.</p><p>We may require identity, trader, tax or payment verification where needed for security, marketplace operation or law. We may refuse registration where we reasonably cannot verify required information or lawfully provide the service.</p></> },
    { id:"service", title:"4. The service and licence", content:<><p>sndbox provides software for building and running automations locally, on self-hosted infrastructure, and on managed services where enabled. Subject to this agreement, we grant you a limited, non-exclusive, non-transferable, revocable licence to use the proprietary parts of the service during your entitlement. Open-source components remain governed by their stated licences.</p><p>Beta, preview and experimental features may be incomplete, change materially, or be withdrawn. We will identify them where reasonably practicable. Do not rely on them for safety-critical or legally mandated processing without your own validation and safeguards.</p></> },
    { id:"licence-boundaries", title:"Licence boundaries and software updates", content:<><p>You may install the desktop software on devices allowed by your plan and make a reasonable backup copy. Except where applicable law or an open-source licence expressly permits it, you must not sell, sublicense, rent, circumvent licence or entitlement checks, extract proprietary source code, remove ownership notices, or use the service to build a substantially substitutable hosted product.</p><p>We may deliver security, compatibility and feature updates. An update may be required to continue using hosted services where an older release is unsafe or incompatible. We will provide updates that consumer law requires to keep digital content or a digital service in conformity for the period a consumer may reasonably expect or for the stated supply period, as applicable. Offline entitlements and grace periods, if offered, do not create a perpetual licence.</p><p>Documentation, system requirements, supported release channels and material limits form part of the service description. Usage limits protect reliability and are applied consistently with the plan shown at order.</p></> },
    { id:"customer-responsibility", title:"5. Your automations and content", content:<><p>You retain rights in workflow definitions, prompts, files, outputs and other material you submit (“Customer Content”). You grant us a worldwide, non-exclusive licence to host, copy, transmit and process Customer Content only as needed to provide, secure, support and improve the service, comply with law, and follow your instructions.</p><p>You are responsible for having all permissions, notices and lawful bases needed for your automation, its inputs and outputs, and the systems or people it affects. You must review outputs and approvals appropriate to the risk. sndbox is a tool and does not replace professional, human or legal review.</p></> },
    { id:"content-controls", title:"Content controls, credentials and outputs", content:<><p>You choose which folders, executables, domains, accounts, browser profiles, APIs, plugins and runners a workflow may access. You must use least privilege, protect exported files and recovery material, review requested plugin permissions, and remove access promptly when an Authorised User leaves. You must not place secrets in fields or logs not designated for secrets.</p><p>Automation can repeat errors quickly. Before production use, test triggers, conditions, retries, idempotency, rate limits, approvals, deletion steps and external side effects. Outputs may be incomplete, outdated, offensive or wrong, particularly where generated by AI or extracted from changing third-party pages. You decide whether an output is fit for use and must maintain human review for decisions that could materially affect a person.</p><p>We may process technical samples of failures only where needed to provide support or protect the service and subject to the Privacy notice and DPA. Customer Content remains confidential as described below.</p></> },
    { id:"third-parties", title:"6. Connections, plugins and third parties", content:<><p>Connections and plugins may access third-party services at your direction. Their own terms and privacy practices apply. You must not use a connection beyond the permissions granted by its owner or circumvent a third party’s technical restrictions. Marketplace plugins may be supplied by independent publishers; their identity and trader status should be displayed on the listing.</p><p>We may disable a connection, plugin or version where required by a provider, law, security issue, or our <Link href="/legal/acceptable-use">Acceptable use policy</Link>.</p></> },
    { id:"payment", title:"7. Plans, billing and tax", content:<><p>Prices, billing period, included usage, taxes and renewal terms are those shown at checkout or in an order form. Unless stated otherwise, subscriptions renew for the same period until cancelled. Metered hosted runner, browser, storage and network use is calculated from service records; local execution is not metered. Card details are handled by the payment provider and do not pass through sndbox servers.</p><p>Prepaid cloud credit is applied to eligible metered use, is not a bank deposit, carries no interest, and cannot be transferred or redeemed for cash except where required by law or our <Link href="/legal/refunds">Refund and cancellation policy</Link>. We may correct manifest metering errors and will provide supporting account records.</p><p>You authorise applicable recurring charges. We may suspend paid features after reasonable notice of failed payment. You remain responsible for properly chargeable amounts and taxes, except taxes on our income.</p></> },
    { id:"orders", title:"Orders, renewals and metering disputes", content:<><p>An Order is accepted when we issue confirmation or enable the paid entitlement, whichever occurs first. Checkout must state the essential service characteristics, total recurring or one-off price including applicable taxes, billing frequency, minimum term, renewal mechanics, cancellation method and compatibility information before the user pays. We will provide confirmation on a durable medium such as email.</p><p>Usage is rounded and minimum-charged only as disclosed beside the applicable meter. Report a metering dispute within 60 days of the statement if reasonably possible, identifying the execution and disputed amount. We will preserve relevant ledger evidence, investigate and correct verified errors. A reporting period does not shorten statutory limitation or consumer rights.</p><p>We may change future prices on reasonable advance notice. A price change does not affect an already-paid fixed term. If you do not accept a renewal price, cancel before renewal. We will not infer consent to a new material charge merely from silence where law requires express agreement.</p></> },
    { id:"consumer-rights", title:"8. Consumer cancellation and conformity rights", content:<>{consumerSavings}<p>UK and Irish consumers normally have 14 days after concluding a distance service contract to cancel without giving a reason. If you expressly ask us to begin a paid service during that period, we may charge a proportionate amount for service supplied before cancellation. A right to cancel downloadable digital content is lost only where the law permits and after the required express consent and acknowledgement. Full instructions and a model form are in our <Link href="/legal/refunds">Refund and cancellation policy</Link>.</p><p>Digital content and digital services must meet applicable statutory standards, including conformity with description, fitness for purpose, quality and required updates. Statutory repair, replacement, price reduction, termination or refund remedies remain available where applicable.</p></> },
    { id:"changes", title:"9. Changes, availability and suspension", content:<><p>We may update the service for security, legal, technical or product reasons. For paid services, we will give reasonable advance notice of a materially detrimental change unless urgent security or legal action prevents it. If such a change materially reduces the paid service, a consumer may have a right to terminate and receive any legally required refund.</p><p>We aim to keep hosted services available but do not promise uninterrupted operation unless an order form states a service level. We may suspend access where reasonably necessary to prevent harm, respond to unlawful use, protect the service, enforce payment, or comply with law. Where lawful and safe, we will give notice and an opportunity to remedy.</p></> },
    { id:"termination", title:"10. Ending the agreement", content:<><p>You may stop using free services at any time and cancel a subscription by contacting us. Cancellation normally takes effect at the end of the paid period, subject to statutory cancellation and refund rights. A clear, accessible online self-service cancellation control must be added before UK subscription sales begin under the rules announced to apply from January 2027. Before closure, export content you need.</p><p>We may terminate for a material breach that is not remedied within a reasonable notice period, or immediately for serious illegality, security risk, insolvency, or where continued supply would breach law. On termination, licences end and we delete or return Customer Content under the applicable retention schedule and DPA. Terms intended to survive—including payment, IP, confidentiality, liability and dispute provisions—continue.</p></> },
    { id:"warranties", title:"11. Warranties", content:<><p>We will provide paid services with reasonable care and skill. We do not promise that every automation will achieve a particular outcome or that third-party websites, APIs, plugins or infrastructure will remain compatible. You must test and supervise automations appropriate to their impact.</p><p>For business users, all implied terms are excluded to the fullest extent permitted by law. No such exclusion applies to a consumer where it would remove a statutory guarantee or remedy.</p></> },
    { id:"confidentiality", title:"Confidentiality", content:<><p>Each party may receive non-public information that is identified as confidential or should reasonably be understood to be confidential. The recipient will use it only to perform or receive the service, protect it with reasonable care, and disclose it only to personnel and professional advisers who need it and owe confidentiality duties.</p><p>This duty does not cover information the recipient can document was lawfully known without restriction, becomes public without breach, is received lawfully from another source, or is independently developed. A legally compelled disclosure is permitted; where lawful, the recipient will give advance notice and reasonable assistance to seek protection. Customer Content and credentials are the customer’s Confidential Information. Security architecture not intentionally published is ours.</p></> },
    { id:"ip-feedback", title:"Intellectual property and feedback", content:<><p>We and our licensors retain rights in sndbox, its design, software, documentation, trade marks and service-generated platform materials. No rights pass except the limited licences expressly granted. You retain Customer Content and any independent rights in workflow logic you create.</p><p>If you voluntarily give product feedback, you grant us a perpetual, worldwide, transferable, sublicensable, royalty-free right to use it without identifying you or disclosing your Confidential Information. This does not transfer ownership of Customer Content or permit us to use personal data outside the Privacy notice.</p><p>Claims that marketplace material infringes intellectual property should follow the notice process in our <Link href="/legal/complaints#illegal-content">Complaints policy</Link>.</p></> },
    { id:"business-indemnity", title:"Business-user indemnity", content:<p>If you use sndbox as a business, you will defend and indemnify us against third-party claims and reasonable losses caused by your unlawful Customer Content, your automation’s unauthorised access or external effects, or your material breach of the Acceptable Use Policy. This applies only to the extent you caused the claim. We must notify you promptly, permit reasonable control of the defence and mitigate loss. You may not settle in a way that admits our fault or imposes non-monetary duties on us without consent.</p> },
    { id:"liability", title:"12. Liability", content:<><p>Nothing limits liability for death or personal injury caused by negligence, fraud or fraudulent misrepresentation, breach of title, deliberate default, or any liability that law does not allow us to limit.</p><p>For consumers, we are responsible for foreseeable loss caused by our breach or failure to use reasonable care and skill. We are not responsible for business losses arising from consumer use, or loss caused by your unlawful use, unsupported configuration, or a third party outside our control. This paragraph does not affect mandatory consumer rights.</p><p>For business users only, neither party is liable for indirect or consequential loss, loss of profit, revenue, goodwill or anticipated savings. Subject to the first paragraph, each party’s aggregate liability arising in any 12-month period is limited to the greater of £100 and the fees paid or payable for the affected service in that period. The cap does not apply to your payment obligations, infringement or misappropriation of the other party’s intellectual property, breach of confidentiality, or indemnities expressly agreed in an order form.</p></> },
    { id:"law", title:"13. Governing law and disputes", content:<><p>Please first use our <Link href="/legal/complaints">Complaints policy</Link>. If you are a consumer resident in the UK or Ireland, the law and courts of your home jurisdiction apply where mandatory law gives you that protection. Otherwise, this agreement is governed by the law of England and Wales and its courts have exclusive jurisdiction.</p><p>The former EU Online Dispute Resolution platform was discontinued on 20 July 2025 and is not offered as a dispute route.</p></> },
    { id:"compliance", title:"Export, sanctions and regulated use", content:<><p>You must comply with applicable export controls, sanctions and trade restrictions and must not make the service available to a prohibited person or for a prohibited end use. You are responsible for sector-specific requirements governing your workflow, including professional secrecy, employment monitoring, electronic marketing, records retention and automated decision-making.</p><p>sndbox is not designed as an emergency service, medical device, payment account, qualified trust service or autonomous control for systems where failure could cause death, personal injury or major environmental damage. Any use in a regulated environment requires your independent assessment, contractual approval where stated, redundancy and human control.</p></> },
    { id:"general", title:"General contract terms", content:<><p>Neither party is liable for delay caused by events beyond reasonable control, but payment obligations already due remain payable and each party must mitigate. Neither party may assign the agreement without consent, not to be unreasonably withheld, except to an affiliate or as part of a genuine merger, reorganisation or sale of substantially all relevant assets, provided the assignee can perform the obligations.</p><p>If a term is unenforceable, it is modified only as much as necessary and the rest continues. A delay in enforcement is not a waiver. These terms do not create a partnership, agency, employment or third-party rights except where expressly stated or mandatory law provides otherwise. Changes must be made under the change clause or in a signed writing. The agreement is the entire agreement about its subject, without excluding liability for fraud.</p></> },
    { id:"contact", title:"14. Notices and contact", content:<><p>Legal notices to us must be sent to <Contact /> and to <span className="legal-required">{c.registeredOffice}</span>. We may send notices to the email associated with your account or through the service. Electronic notices are treated as received when sent unless the sender receives a delivery failure.</p><p>Effective {c.effectiveDate}. Version {c.version}.</p></> },
  ],
};

const privacy: LegalDocument = {
  slug:"privacy", shortTitle:"Privacy", title:"Privacy notice",
  summary:"How sndbox handles personal data across the website, accounts, cloud services, support and marketplace.",
  audience:"Visitors, users, workspace members, publishers and contacts",
  sections:[
    {id:"controller",title:"1. Controller and scope",content:<>{identity}<p>For account administration, billing, security, marketing-site enquiries and marketplace operation, sndbox is the controller. When a customer uses hosted execution to process personal data in Customer Content, the customer normally determines the purposes and means and is the controller; sndbox acts as processor under our <Link href="/legal/data-processing-addendum">Data Processing Addendum</Link>. Local-only workflows and credentials remain on the user’s device unless the user chooses a hosted or sync feature.</p><p>Privacy contact: <Contact kind="privacy" />. Establishment: <span className="legal-required">{c.establishment}</span>. EU representative: <span className="legal-required">{c.euRepresentative}</span>. UK representative: <span className="legal-required">{c.ukRepresentative}</span>.</p></>},
    {id:"data",title:"2. Data we collect",content:<ul><li><strong>Account and identity:</strong> name, email, identity-provider subject, organisation, roles, authentication events and session metadata.</li><li><strong>Commerce:</strong> plan, licence, billing address where provided, payment-provider customer and transaction references, credit balance, metered usage, invoices and refunds. We do not receive full card details.</li><li><strong>Product and Customer Content:</strong> workflow metadata and, when hosted features are chosen, encrypted workflow content, execution inputs and outputs, logs, artifacts, webhook deliveries, browser-profile references, environment and runner information.</li><li><strong>Security and operations:</strong> IP address, timestamps, device/session identifiers, audit events, command receipts, error and bounded diagnostic data. Secret-like fields are redacted from diagnostics.</li><li><strong>Marketplace:</strong> publisher identity, contact and trader-verification information, signing keys, listings, packages, reviews, purchases and moderation history.</li><li><strong>Communications:</strong> contact enquiries, support cases, consent records and correspondence.</li><li><strong>Referral data:</strong> referral code, attribution and resulting reward records.</li></ul>},
    {id:"content-detail",title:"Customer Content, credentials and sensitive data",content:<><p>The categories inside Customer Content are chosen by the customer, not sndbox. Depending on a workflow, they can include contact data, communications, employment or customer records, documents, browser content and online identifiers. A workflow could also process special-category data or criminal-offence data even though sndbox does not require it. Customers must assess necessity, Article 9/10 conditions, safeguards and DPIA requirements before submitting such data.</p><p>Connection secrets, API keys and protected variables are stored in designated protected systems and are excluded from ordinary logs and account exports. Local credentials are kept in the operating-system credential store. Hosted protected values are encrypted. Metadata such as connection name, type, scope and expiry can still be processed so the service can manage the connection.</p><p>Browser automation may encounter form fields, cookies, pages, screenshots and downloads. Password fields and elements marked sensitive are masked in screenshots; diagnostic URLs omit credentials, query strings and fragments. Customers must avoid capturing unrelated personal data and configure retention appropriate to the target service.</p></>},
    {id:"sources",title:"3. Where data comes from",content:<p>We obtain data from you; workspace owners and administrators; your identity provider; payment provider; connected services at your direction; publishers and marketplace users; runners and software you operate; security and operational events; and referral links. Customer Content may contain personal data about other people. Customers are responsible for giving them any required notice.</p>},
    {id:"purposes",title:"4. Purposes and legal bases",content:<div className="legal-table-wrap"><table><thead><tr><th>Purpose</th><th>Typical data</th><th>UK/EU GDPR basis</th></tr></thead><tbody><tr><td>Provide accounts, software, cloud execution, support and purchases</td><td>Identity, content, usage, commerce, communications</td><td>Contract; steps requested before contract</td></tr><tr><td>Authenticate, prevent fraud, secure and troubleshoot the service</td><td>Session, IP, audit, diagnostics and security events</td><td>Legitimate interests in secure and reliable services; legal obligation where applicable</td></tr><tr><td>Bill, account, tax and meet regulatory duties</td><td>Commerce, verification and records</td><td>Contract and legal obligation</td></tr><tr><td>Operate and moderate the marketplace</td><td>Publisher, listing, review, purchase and report data</td><td>Contract, legal obligation and legitimate interests in a trustworthy marketplace</td></tr><tr><td>Respond to enquiries and improve the service</td><td>Communications and appropriately minimised product telemetry</td><td>Contract or legitimate interests in support and product improvement</td></tr><tr><td>Send optional marketing</td><td>Email and preferences</td><td>Consent, or a lawful soft opt-in where available; you may opt out at any time</td></tr></tbody></table><p>We do not use Customer Content to train general-purpose AI models unless a separate, explicit agreement says so. We do not make solely automated decisions that produce legal or similarly significant effects about individuals.</p></div>},
    {id:"interests",title:"Our legitimate interests",content:<><p>Where we rely on legitimate interests, they are: securing accounts and infrastructure; preventing fraud, abuse and unauthorised access; maintaining reliability; diagnosing faults; understanding service capacity; enforcing agreements; protecting legal rights; improving features using minimised information; and operating a trustworthy marketplace. We assess necessity and balance these interests against the individual’s rights, expectations and possible harm.</p><p>You may object based on your particular situation. We will stop unless we demonstrate compelling legitimate grounds overriding your interests, rights and freedoms, or need the data for legal claims. Direct marketing stops when you object. Consent is never bundled as a condition where the processing is not necessary for the service.</p></>},
    {id:"workspace",title:"Workspace administrators and other controllers",content:<><p>An organisation that provides your workspace may control account membership, roles, workflows, audit history, retention, connections and exports. It may access data associated with the organisational workspace under its own policies. Ask that organisation about its processing. When you leave, it may retain workspace records it controls.</p><p>Third-party connection providers, plugin publishers, payment networks and customer-selected self-hosted operators can be independent controllers or processors under their own terms. The identity provider handles sign-in data under its arrangement with sndbox or the customer. Our role depends on who determines each processing purpose; one label does not apply to every data flow.</p></>},
    {id:"sharing",title:"5. Sharing and processors",content:<><p>We disclose data only as needed to: infrastructure, storage, identity, email, observability, support and payment providers; a workspace’s authorised members and service accounts; publishers or buyers where needed for a transaction; connected third-party services at your direction; professional advisers and auditors; a buyer in a genuine corporate transaction; and public authorities or others where lawfully required or necessary to protect rights and safety.</p><p>Current processor information is on the <Link href="/legal/subprocessors">Subprocessors page</Link>. Payment providers and third-party connections may act as independent controllers for their own purposes.</p></>},
    {id:"transfers",title:"6. International transfers",content:<p>Data may be processed outside the UK or EEA if a provider, customer-selected runner or connection is located elsewhere. Where transfer rules apply, we use an adequacy decision/regulation or appropriate safeguards such as the European Commission’s 2021 Standard Contractual Clauses and, for UK restricted transfers, the ICO’s International Data Transfer Addendum or IDTA, together with required risk assessments and supplementary measures. Contact us for a copy of applicable safeguards.</p>},
    {id:"disclosure",title:"Required disclosure and corporate events",content:<><p>We assess government and law-enforcement requests for legal validity, scope and jurisdiction. Where lawful, we seek to narrow overbroad requests and notify the affected customer before disclosure. We disclose only what is required and record the decision, unless law prohibits notice or recording. Emergency disclosure is limited to a good-faith belief that it is necessary to prevent imminent serious harm and is reviewed afterwards.</p><p>If ownership of all or part of the business changes, relevant data may be disclosed under confidentiality for due diligence and transferred to the successor. We will continue to protect it under this notice and provide notice of material controller changes where required.</p></>},
    {id:"retention",title:"7. Retention",content:<><p>Workspace settings control some hosted retention. Defaults are: execution events and payload references 90 days; terminal queue and attempt history 30 days; encrypted webhook deliveries 7 days; completed runner commands 30 days; and workspace audit events 2,555 days. Configurable periods may vary within product limits. Outcome summaries, deletion receipts and records needed for security, disputes, legal compliance or financial accounting may remain longer.</p><p>Billing and invoice reconciliation records follow applicable tax and accounting periods. Enquiries, support cases, marketplace verification, incident records and security logs are kept only for documented operational or legal periods, which must be finalised in the production retention schedule. Backups expire on a controlled cycle. Account deletion revokes credentials, pseudonymises identity and cryptographically erases personal workflow ciphertext, subject to records we must retain.</p></>},
    {id:"rights",title:"8. Your rights",content:<><p>Subject to conditions and exemptions, UK and Irish/EEA individuals may request access, correction, erasure, restriction, portability, or object to processing. Where processing relies on consent, it may be withdrawn at any time without affecting earlier processing. You may also object to direct marketing at any time.</p><p>Use the account export and deletion controls where available or contact <Contact kind="privacy" />. We may verify identity and normally respond within one month, subject to a lawful extension. You may complain to the <External href="https://ico.org.uk/make-a-complaint/data-protection-complaints/">UK Information Commissioner</External> or Ireland’s <External href="https://www.dataprotection.ie/en/individuals/exercising-your-rights/raising-concern-commission">Data Protection Commission</External>, or another competent supervisory authority.</p></>},
    {id:"rights-process",title:"How rights requests are handled",content:<><p>Describe the right you wish to exercise and the account, workspace or processing involved. We may request proportionate information to confirm identity and authority, particularly where disclosure could expose Customer Content or another person’s data. An authorised agent must show authority. We do not require more identity data than reasonably necessary.</p><p>We ordinarily respond without undue delay and within one month. Under the EU GDPR, a complex or numerous request may be extended by up to two further months with notice. Under the UK GDPR, applicable time-limit rules and any lawful pause while awaiting identification or clarification apply. Requests are normally free; a reasonable fee or refusal may apply only where law permits for manifestly unfounded or excessive requests.</p><p>Portability applies to data you provided, processed by automated means on consent or contract, and is supplied in a structured, commonly used, machine-readable format where technically feasible. Erasure does not apply where retention is required for law, freedom of expression, public interest or legal claims. Restriction may preserve data without ordinary use while accuracy, objection or legality is considered.</p></>},
    {id:"privacy-complaints",title:"Privacy complaints",content:<><p>You can make a data-protection complaint electronically through <Link href="/contact?type=privacy">the privacy contact route</Link>. We will acknowledge a UK data-protection complaint within 30 days as required by section 164A of the Data Protection Act 2018, investigate to an appropriate extent, keep you informed of material progress and communicate the outcome without undue delay. Our target acknowledgement of 3 business days is faster but is not a statutory deadline.</p><p>You do not have to complain to us before approaching a supervisory authority, although doing so may let us resolve the issue sooner. Retaliation for a good-faith complaint is prohibited.</p></>},
    {id:"security",title:"9. Security",content:<p>We use measures appropriate to risk, including encryption of protected hosted values, OS credential storage for local secrets, access control, signed runner commands and plugin packages, network restrictions, audit logging, redaction, isolated managed-browser workloads and controlled support access. No system is perfectly secure. Please report suspected vulnerabilities under our <Link href="/legal/vulnerability-disclosure">Vulnerability Disclosure Policy</Link>.</p>},
    {id:"breaches",title:"Personal data breaches",content:<p>We maintain incident detection, containment, investigation, recovery and evidence procedures. Where sndbox is controller, we will notify the competent supervisory authority within the legally required period when the risk threshold is met and notify affected individuals without undue delay where high risk requires it. Where sndbox is processor, we notify the customer without undue delay after becoming aware and support its assessment under the DPA. A notice may arrive in stages as facts become available.</p>},
    {id:"cookies-privacy",title:"Cookies and communications",content:<><p>Our <Link href="/legal/cookies">Cookie and storage policy</Link> identifies browser technologies, durations and consent status. Optional marketing messages include a working opt-out and are sent only where PECR, Ireland’s ePrivacy Regulations and data protection law permit. Transactional messages about authentication, billing, security, service operation and requested support are not marketing merely because they use email.</p><p>We keep suppression information after an opt-out so we can honour it. Withdrawing marketing consent does not end the account or stop necessary service messages.</p></>},
    {id:"children",title:"10. Children",content:<p>sndbox is intended for adults and organisational use, not children. We do not knowingly offer accounts to anyone under 18. Contact us if you believe a child has provided personal data.</p>},
    {id:"changes",title:"11. Changes and legal framework",content:<><p>This notice is intended to meet Articles 12–14 of the EU GDPR, the UK GDPR, the UK <External href="https://www.legislation.gov.uk/ukpga/2018/12/contents">Data Protection Act 2018</External> (as amended, including by the Data (Use and Access) Act 2025), and Ireland’s <External href="https://www.irishstatutebook.ie/eli/2018/act/7/enacted/en/html">Data Protection Act 2018</External>. We will post material changes and, where required, give direct notice.</p><p>Effective {c.effectiveDate}. Version {c.version}.</p></>},
  ]
};

const cookies: LegalDocument = {
  slug:"cookies",shortTitle:"Cookies",title:"Cookie and storage policy",summary:"The browser storage sndbox uses, why it is needed, and how long it lasts.",audience:"Website and account-portal visitors",
  sections:[
    {id:"summary",title:"1. Our current approach",content:<><p>The public marketing site does not intentionally set advertising or analytics cookies. The account portal uses strictly necessary cookies for sign-in, security and navigation. A referral-attribution cookie also exists in the current code; because it is not essential to provide the requested account service, it must be held back in the UK and Ireland until a compliant consent control is implemented.</p><p>We will not set non-essential cookies or similar tracking technologies before obtaining the consent required by UK PECR or Ireland’s ePrivacy Regulations. This policy covers storage on sndbox.app and app.sndbox.app. Desktop application preferences and isolated automation browser profiles are described separately below.</p></>},
    {id:"table",title:"2. Cookie list",content:<div className="legal-table-wrap"><table><thead><tr><th>Name</th><th>Purpose</th><th>Duration</th><th>Basis</th></tr></thead><tbody><tr><td><code>sandbox_session</code></td><td>Authenticates the account portal; HTTP-only</td><td>Up to 8 hours</td><td>Strictly necessary</td></tr><tr><td><code>sandbox_oidc_state</code></td><td>Prevents sign-in request forgery</td><td>10 minutes</td><td>Strictly necessary</td></tr><tr><td><code>sandbox_oidc_verifier</code></td><td>PKCE sign-in security</td><td>10 minutes</td><td>Strictly necessary</td></tr><tr><td><code>sandbox_oidc_return</code></td><td>Returns you to the requested portal page after sign-in</td><td>10 minutes</td><td>Strictly necessary</td></tr><tr><td><code>sandbox_referral</code></td><td>Attributes a referral for reward and reporting</td><td>30 days</td><td>Consent required; must not be set before consent</td></tr></tbody></table></div>},
    {id:"cookie-detail",title:"How the technologies work",content:<><p>A cookie is a small value stored by a browser and returned to the relevant domain. Session and OIDC cookies contain authentication or random protocol values, not a readable profile. <code>HttpOnly</code> prevents ordinary page scripts from reading protected cookies; <code>Secure</code> restricts them to HTTPS in production; <code>SameSite=Lax</code> reduces cross-site request risk while allowing the top-level sign-in return.</p><p>The identity provider and payment checkout operate on their own domains and may set cookies necessary for authentication, fraud prevention or payment. Their notices govern those cookies. We must identify the selected production providers and link their notices before launch.</p><p>Server logs can record request IP address, user agent, requested path, timestamp and security outcome without using a browser cookie. Those logs are covered by the Privacy notice and are not used for cross-site advertising.</p></>},
    {id:"control",title:"3. Your controls",content:<><p>You can delete or block cookies in browser settings, but blocking necessary cookies will prevent sign-in and some requested functions. If we later introduce optional analytics, advertising or preference storage, we will update this table and provide an equally easy way to accept, reject and withdraw consent.</p><p>Sign out to invalidate the active portal session. Referral storage can be removed through browser controls.</p></>},
    {id:"consent",title:"Consent requirements and records",content:<><p>Where consent is required, the choice must be freely given, specific, informed and an unambiguous affirmative action. Continuing to browse, inactivity, a pre-ticked control or a design that makes rejection harder is not consent. Optional technologies must remain off until the relevant choice is recorded.</p><p>A consent tool should let users accept or reject purposes at the same level, revisit the choice from every page and withdraw as easily as they consented. We may keep a minimal record of the consent version, purposes, choice, timestamp and pseudonymous identifier to demonstrate compliance. Withdrawal prevents future use but does not invalidate earlier lawful processing.</p><p>Consent should be refreshed when purposes or vendors materially change and otherwise at an interval justified by the technology and regulator guidance. Necessary cookies cannot be disabled within our service, but browser controls remain available.</p></>},
    {id:"inventory",title:"Change control",content:<p>Engineering must complete a cookie and local-storage scan before each production release that adds a script, SDK, embedded media, chat widget, payment flow or identity provider. No vendor may be classified as strictly necessary merely because it is useful to sndbox. The public table must be updated before the technology is enabled, including provider, domain, purpose, duration, data recipients and consent category.</p>},
    {id:"desktop",title:"4. Desktop and automation storage",content:<p>The desktop application stores preferences and workflow data locally. Managed browser profiles may retain cookies and site storage when you explicitly choose a persistent profile; those are cookies of the sites you automate, not sndbox marketing cookies. Clearing or deleting the profile removes its retained browser storage. Cloud profile import is explicit, expiring and audited.</p>},
    {id:"signals",title:"Browser signals and similar technologies",content:<p>We do not currently claim to honour a browser “Do Not Track” signal because there is no single legally binding interpretation for it. A legally recognised opt-out signal will be handled where applicable. Pixels, SDK identifiers, local storage, fingerprinting and link-decoration used to store or access terminal information are subject to the same consent analysis as cookies and may not be introduced without review.</p>},
    {id:"law",title:"5. Law and contact",content:<><p>The relevant rules include the UK <External href="https://www.legislation.gov.uk/uksi/2003/2426/contents">Privacy and Electronic Communications Regulations 2003</External> and Ireland’s <External href="https://www.irishstatutebook.ie/eli/2011/si/336/made/en/print">European Communities (Electronic Communications Networks and Services) (Privacy and Electronic Communications) Regulations 2011</External>, read with applicable data protection law. See the <External href="https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/guide-to-pecr/cookies-and-similar-technologies/">ICO cookie guidance</External> and <External href="https://www.dataprotection.ie/en/dpc-guidance/guidance-cookies-and-other-tracking-technologies">Irish DPC cookie guidance</External>.</p><p>Questions: <Contact kind="privacy" />. Effective {c.effectiveDate}.</p></>}
  ]
};

const acceptableUse: LegalDocument = {
  slug:"acceptable-use",shortTitle:"Acceptable use",title:"Acceptable use policy",summary:"Safety and conduct rules for workflows, runners, browser automation, APIs and marketplace content.",audience:"All users, administrators and publishers",
  sections:[
    {id:"principle",title:"1. Principle",content:<p>Use sndbox lawfully, with permission, and in a way that does not harm people, systems or the service. You are responsible for the automation you design, the targets it reaches, its frequency and effects, and appropriate human review.</p>},
    {id:"prohibited",title:"2. Prohibited activity",content:<ul><li>Unauthorised access, credential theft, phishing, malware, ransomware, botnets, destructive payloads or evasion of security controls.</li><li>Scanning, scraping, browser automation or API use contrary to law, contractual restrictions or a system owner’s permission.</li><li>Fraud, deception, impersonation, unlawful surveillance, spam, harassment, discrimination, exploitation or facilitation of violence.</li><li>Content or activity that infringes privacy, confidentiality, intellectual property, consumer, export-control or other rights.</li><li>Child sexual abuse material, grooming, trafficking, intimate-image abuse or any sexual exploitation of minors. Do not upload or forward suspected illegal material when reporting it; report through the appropriate authority.</li><li>High-impact decisions about employment, housing, credit, insurance, education, policing, migration, health or legal rights without lawful authority, meaningful human oversight, testing and required safeguards.</li><li>Weapons development, sanctions evasion, unlawful gambling, manipulation of civic processes, or other regulated activity without all required licences and controls.</li><li>Excessive traffic, denial of service, bypassing rate limits, cryptomining, resale of access without approval, or interference with other users.</li><li>Publishing secrets, personal data, malicious code, misleading listings or undisclosed commercial communications in the marketplace.</li></ul>},
    {id:"automation",title:"Automation-specific safeguards",content:<ul><li>Respect robots, API limits, access controls and the target service’s applicable terms. Possession of a credential does not by itself prove authority.</li><li>Do not automate consent, signatures, purchases, public posts, employment action, account closure or other consequential acts without an authorised person understanding and approving the effect where appropriate.</li><li>Use idempotency, rate limits and bounded retries so a failure cannot cause duplicate messages, payments, deletions or requests.</li><li>Maintain a tested stop mechanism for recurring or high-volume workflows and monitor unattended executions.</li><li>Do not disguise automation where law or a platform requires disclosure. Do not evade CAPTCHAs, access queues, paywalls or anti-abuse systems.</li><li>Minimise personal data and secrets in prompts, logs, screenshots and artifacts. Honour deletion, objection and suppression lists.</li></ul>},
    {id:"high-risk",title:"High-risk and regulated contexts",content:<><p>You may not use sndbox as the sole basis for a decision producing legal or similarly significant effects for a person. Where a lawful high-impact use is permitted, you must conduct an impact assessment, validate data and outcomes, provide meaningful human review, explain the decision where required, allow challenge and correction, and monitor for discrimination and drift.</p><p>You must not represent sndbox output as professional medical, legal, financial, safety or compliance advice. Workflows involving health data, children, biometric identification, criminal-offence data, employee monitoring or essential services require documented necessity, proportionality, access controls and any regulator or customer approval.</p></>},
    {id:"resources",title:"Fair use of shared resources",content:<p>Published technical limits, concurrency controls, storage quotas and rate limits form part of this policy. You may not split accounts, rotate identifiers or use self-hosted components to evade a restriction. We may throttle abusive or unstable workloads. If legitimate use requires higher limits, contact us before deployment so capacity and risk can be assessed.</p>},
    {id:"enforcement",title:"Detection and enforcement",content:<><p>We may use rate, error, malware, permission and security signals to detect policy violations. We do not claim a general right to inspect Customer Content indiscriminately. Investigation access must be necessary, proportionate, authorised and logged, with customer-approved support access used where applicable.</p><p>Responses may include warning, required remediation, throttling, quarantine, capability removal, plugin revocation, suspension or termination. We consider severity, intent, recurrence, harm, cooperation and the rights of affected people. Imminent threats, child-safety matters, malware and credible unlawful access may require immediate action without advance notice.</p><p>Where law requires, we give a statement of reasons and a meaningful appeal. We may preserve relevant evidence and cooperate with competent authorities. Enforcement does not limit our right to recover losses or seek urgent relief.</p></>},
    {id:"reporting",title:"Reporting suspected abuse",content:<p>Use <Link href="/legal/complaints#illegal-content">our notice process</Link> and identify the exact workflow-facing surface, listing, publisher, URL or account where possible. Explain the rule or law involved and the risk of delay. Do not test, access or download more data than needed to report. False, abusive or manifestly unfounded reports may be restricted after warning, but good-faith mistakes are not penalised.</p>},
    {id:"report",title:"5. Reporting and appeal",content:<p>Report abuse or appeal a decision through our <Link href="/legal/complaints">Complaints policy</Link>. Security vulnerabilities belong under the <Link href="/legal/vulnerability-disclosure">Vulnerability Disclosure Policy</Link>. If someone is in immediate danger, contact emergency services. Effective {c.effectiveDate}.</p>}
  ]
};

const marketplaceTerms: LegalDocument = {
  slug:"marketplace-terms",shortTitle:"Marketplace",title:"Marketplace terms",summary:"Rules for discovering, buying, installing and reviewing third-party plugins.",audience:"Marketplace visitors, buyers and workspace administrators",
  sections:[
    {id:"role",title:"1. Marketplace roles",content:<><p>sndbox operates the marketplace and technical distribution service. A listing must identify whether the publisher is sndbox or an independent trader/non-trader. Unless the listing says sndbox is the publisher, the publisher—not sndbox—licenses and is responsible for the plugin, its claims, support and legal compliance. sndbox remains responsible for its own marketplace obligations and any payment or service it expressly supplies.</p><p>Do not buy until the listing clearly identifies the contracting trader, total price and taxes, functionality, compatibility, permissions, support, update terms and cancellation information. If required information is absent, report the listing and do not transact.</p></>},
    {id:"formation",title:"Contract formation and trader status",content:<><p>A marketplace listing is an invitation to order unless it expressly says otherwise. The seller accepts when it issues confirmation or enables the entitlement. The receipt must identify the seller, the plugin and version or entitlement, price and tax, licence, support contact and applicable cancellation information on a durable medium.</p><p>A “trader” acts for purposes relating to its trade, business, craft or profession. A non-trader does not. EU consumers do not receive EU consumer-law rights from a non-trader merely because the transaction occurs through an online marketplace; the listing must clearly display that status. sndbox must not permit an Irish/EEA consumer purchase until required trader traceability and pre-contract fields are complete.</p><p>If sndbox is merchant of record or reseller for a listing, checkout must say so and these Marketplace Terms and the receipt will identify which obligations sndbox assumes. Payment collection alone does not silently make sndbox the plugin developer.</p></>},
    {id:"licence",title:"2. Licence and installation",content:<><p>Your right to use a plugin comes from the publisher’s displayed licence. Installation is limited to the account or workspace and seats shown at purchase. You may inspect requested capabilities and network domains before approval. Each workflow revision pins an exact plugin version and integrity digest; updates that add permissions require fresh administrator review.</p><p>Plugins run behind a capability-controlled interface, but review and sandboxing cannot eliminate all risk. Administrators must evaluate permissions, data access, publisher terms and suitability.</p></>},
    {id:"updates",title:"Updates, compatibility and security",content:<><p>The listing must state supported sndbox versions, dependencies, operating environments and the expected update/support period. Publishers must provide updates required to maintain statutory conformity and remediate material security issues during that period. A functional update may change behaviour; permission additions are highlighted and require administrator approval.</p><p>We may revoke a specific digest immediately where continued execution presents a credible security or legal risk. Revocation prevents new installs and runs but should preserve configuration and evidence for review and rollback. We may distribute an emergency notice, safe replacement or refund instructions. A customer should not bypass revocation controls.</p></>},
    {id:"orders",title:"3. Orders, payment and refunds",content:<p>We will show whether sndbox acts as seller, reseller or collection agent before purchase. Charges and payout allocation follow the checkout and applicable publisher agreement. Consumer cancellation, conformity and refund rights cannot be excluded and are explained in the <Link href="/legal/refunds">Refund and cancellation policy</Link>. A publisher cannot replace statutory rights with a narrower policy.</p>},
    {id:"ranking",title:"4. Ranking, review and verification",content:<><p>Default marketplace ordering may use recency, relevance to a query, compatibility, price filters, verification status and operational integrity. Paid placement will be labelled and is not currently represented in this repository. Publisher “verified” status means identity and listing control were reviewed; it is not an endorsement or guarantee.</p><p>Each version undergoes automated checks and human review of declared capabilities, network access, licence, privacy and behaviour. Approval is version-specific. Reviews may miss defects or undisclosed behaviour.</p></>},
    {id:"recommendations",title:"Search and recommendations",content:<><p>Search may match names, descriptions, categories, permissions and documentation. Filters selected by the user narrow results. A default “recent” ordering prioritises publication recency; a compatibility check may exclude versions that cannot run on the user’s host release. Verification and safety restrictions can affect eligibility and visibility.</p><p>We do not currently describe a personalised recommender or paid ranking system in this repository. If either is introduced, the interface and these terms must disclose the main parameters, relative importance, user controls and commercial influence before activation, as required by applicable platform law.</p></>},
    {id:"moderation",title:"5. Moderation and notices",content:<><p>We may reject, suspend or remove a listing or version for illegality, infringement, deception, malware, undisclosed permissions, security risk, policy breach or material quality failure. We apply restrictions diligently, objectively and proportionately and provide reasons and an appeal route where legally required. Security revocation blocks new installation and execution of the affected digest while preserving configuration for inspection.</p><p>To report illegal or infringing content, use the process in our <Link href="/legal/complaints#illegal-content">Complaints policy</Link>. A valid notice should identify the exact listing or content, explain why it is illegal, include the reporter’s name and email (except where law permits otherwise), and contain a good-faith statement. We acknowledge notices and communicate decisions where required.</p></>},
    {id:"decision-process",title:"Restriction and appeal procedure",content:<><p>Except where urgent action is necessary, a restriction notice should identify the affected content or account, facts relied on, contractual or legal ground, territorial scope, duration, whether automation assisted the decision, and available redress. We distinguish package rejection, listing suspension, version revocation, removal and account restriction because each has a different effect.</p><p>An internal appeal is reviewed by appropriately qualified personnel with authority to reverse the decision and is not decided solely by automation. We consider the rights and legitimate interests of the publisher, reporter, customers and affected people. Reinstatement does not prevent later action based on new evidence.</p></>},
    {id:"reviews-content",title:"Reviews and user submissions",content:<p>If ratings, reviews or discussions are enabled, contributors grant sndbox a non-exclusive licence to host, display and moderate that content for the marketplace. Reviews must reflect genuine experience and disclose incentives or commercial relationships. We may label verified purchases, detect coordinated manipulation, remove unlawful or irrelevant content, and preserve moderation evidence. We will not suppress a negative review merely because it is critical.</p>},
    {id:"dsa",title:"6. Platform regulation",content:<><p>For recipients in Ireland and the EEA, marketplace hosting may be subject to the <External href="https://eur-lex.europa.eu/eli/reg/2022/2065/oj">Digital Services Act (EU) 2022/2065</External>. Our terms describe moderation restrictions and complaint routes. Publisher onboarding must obtain and reasonably verify trader traceability information before allowing an EU consumer transaction, and relevant trader identity information must appear on the listing.</p><p>Contact point for recipients and authorities: <Contact />. Languages accepted: English. DSA legal representative: <span className="legal-required">{c.dsaLegalRepresentative}</span>. The operator must determine and publish its EU monthly active recipient figure, establishment/representative status and any applicable transparency report before launch.</p><p>The marketplace may also be a user-to-user service under the UK <External href="https://www.legislation.gov.uk/ukpga/2023/50/contents">Online Safety Act 2023</External>. Before public launch, the operator must document the required service, illegal-content and children’s-access assessments and implement the resulting reporting, risk, record-keeping and safety duties. An 18+ contractual rule does not by itself resolve that assessment.</p></>},
    {id:"liability",title:"7. Responsibility and disputes",content:<><p>Report plugin problems promptly and stop using a plugin you reasonably believe unsafe. For independent-publisher disputes, contact the publisher first and copy us if the listing or marketplace is involved. Our liability is governed by the <Link href="/legal/terms">Terms of service</Link>; consumer statutory rights remain unaffected.</p><p>Effective {c.effectiveDate}.</p></>}
  ]
};

const publisherTerms: LegalDocument = {
  slug:"publisher-terms",shortTitle:"Publishers",title:"Publisher terms",summary:"The submission, security, support, moderation and commercial terms for plugin publishers.",audience:"People and organisations publishing plugins",
  sections:[
    {id:"agreement",title:"1. Agreement and authority",content:<p>These Publisher Terms supplement the <Link href="/legal/terms">Terms of service</Link>. You confirm that your publisher information is accurate, you have authority to publish and license every submission, and you will promptly update contact, trader, tax and payout information. For EU consumer offerings, you must provide the trader information required by Article 30 of the Digital Services Act and self-certify compliance with applicable EU law.</p>},
    {id:"onboarding",title:"Publisher onboarding and account security",content:<><p>You must provide the legal or personal name, public trading name, geographic address, telephone, email, trade-register details where applicable, payment account, tax information and identity evidence reasonably required for trader traceability, sanctions screening, payment and fraud prevention. sndbox may verify information against reliable official sources and may withhold publishing until checks are complete.</p><p>Publisher members must use individual accounts, least-privilege roles and separate signing keys. You are responsible for membership changes, key custody and activity under authorised credentials. Notify us immediately of suspected account or signing-key compromise. Key revocation blocks new submissions but does not silently rewrite previously signed packages.</p><p>You may not transfer a publisher identity, impersonate another developer, hide beneficial control or create replacement accounts to evade a restriction.</p></>},
    {id:"submission",title:"2. Submission requirements",content:<ul><li>Use a unique version and immutable package; accurately declare code, dependencies, licences, data practices, price, support, capabilities and network domains.</li><li>Sign with an authorised publisher key and protect private keys. Notify us immediately of compromise.</li><li>Do not submit malware, hidden behaviour, deceptive claims, copied content, secrets or permissions unrelated to stated functions.</li><li>Provide documentation, testing evidence, vulnerability contact and any information reasonably needed for review or legal compliance.</li><li>Keep the plugin compatible and provide legally required security and conformity updates for the promised support period.</li></ul>},
    {id:"quality",title:"Quality, documentation and changes",content:<><p>A submission must perform the material functions described, fail safely, validate inputs, avoid unnecessary data collection and handle retries without unintended duplicate effects. Documentation must explain setup, permissions, external communications, data retention, pricing, support, known material limitations and deletion/uninstall effects.</p><p>Release notes must identify security fixes, breaking changes, new data uses, permission additions and migration steps. You must increment versions in accordance with the published scheme and may not replace uploaded bytes or reuse a version or digest. A new version receives a new review and cannot inherit approval.</p><p>You must test on stated supported versions and preserve evidence sufficient to reproduce the submitted build. Scanner success is not a warranty from sndbox and does not reduce your responsibility.</p></>},
    {id:"licence",title:"3. Rights you grant",content:<><p>You retain ownership. You grant sndbox a worldwide, non-exclusive, royalty-free licence during the listing and a reasonable wind-down period to host, scan, reproduce, test, display, distribute and make technical transformations necessary to operate, secure and promote the marketplace. You grant customers the licence displayed on the listing and cannot retroactively narrow rights for versions already purchased.</p><p>You permit use of your name, marks and listing assets solely to identify and promote your plugin. You warrant that you have all rights needed for these grants.</p></>},
    {id:"review",title:"4. Review and moderation",content:<><p>Automated scanning checks package integrity, signatures, declared contents, WebAssembly imports, dependencies, malware indicators, capability use and reproducibility evidence. Human reviewers decide publication; AI does not make the final approval decision. Approval applies only to the exact version.</p><p>We may request changes, reject, rank lower, suspend, revoke or remove content under published policies and applicable law. Except for urgent threats, we will normally explain the ground and offer an internal appeal. You must cooperate with recalls, customer notices and remediation.</p></>},
    {id:"customers",title:"5. Customers and support",content:<p>You are responsible for accurate pre-contract information, licence performance, support and legal guarantees for plugins you supply. You must respond to security issues and consumer conformity claims promptly. Do not access Customer Content except through disclosed, approved capabilities and a valid legal basis. Your privacy notice must identify your role, data uses, recipients, retention and transfers.</p>},
    {id:"privacy-security",title:"Privacy and security duties",content:<><p>Before processing personal data, determine whether you are controller, joint controller or processor and put required agreements in place. Request only necessary capabilities; use data solely for disclosed purposes; honour rights requests; keep a retention schedule; secure transfers; and delete data when no longer needed. If you act as the customer’s processor, your terms must meet Article 28 and you may appoint subprocessors only with required authorisation.</p><p>Notify sndbox without undue delay of a vulnerability, credential exposure, malicious dependency, unlawful access or personal data breach that could affect a listing, package, customer or the marketplace. Give enough information for containment and customer/regulator assessment, preserve relevant evidence, cooperate with remediation and do not make misleading public statements.</p><p>Credentials obtained through a capability may not be exported, logged, sold, used for advertising or reused outside the customer-directed operation. A plugin may not fingerprint users or introduce tracking undisclosed in the listing and privacy notice.</p></>},
    {id:"commercial",title:"6. Pricing, payouts and tax",content:<><p>Commercial commission, payment timing, reserves, refunds, chargebacks, currency, tax handling and payout-provider terms must be stated in an accepted publisher order before paid publication. Because those terms are not configured in this repository, no paid listing may be published under this draft alone.</p><p>We may withhold amounts reasonably connected to refunds, fraud, chargebacks, sanctions, tax documentation or breach, and will provide an account. You are responsible for taxes on your income unless law requires us to collect, deduct or report them.</p></>},
    {id:"records-audit",title:"Records, audit and regulator cooperation",content:<p>Keep current source, dependency, build, licence, security-test, support and transaction records for the support period and any longer legally required period. On reasonable notice, provide evidence directly relevant to a review, security event, consumer claim or regulatory duty. Any audit must be proportionate and protect source-code confidentiality. You must cooperate with lawful product-safety, consumer, data-protection, tax, sanctions and platform-regulation requests.</p>},
    {id:"indemnity",title:"7. Business indemnity and liability",content:<><p>You will defend and indemnify sndbox against third-party claims and reasonable losses arising from your plugin, listing, infringement, unlawful data processing, consumer-law breach or violation of these terms, except to the extent caused by sndbox. We will give prompt notice and reasonable control of the defence; no settlement may admit our fault or impose non-monetary obligations without consent.</p><p>The business liability provisions in the Terms of service apply. Nothing limits liabilities that cannot legally be limited.</p></>},
    {id:"end",title:"8. Ending publication",content:<p>You may unpublish subject to existing customer rights, security duties and any wind-down requirement. We may retain immutable packages, review evidence, purchase records and security history as legally or operationally necessary. Sections concerning licences already granted, payment, IP, confidentiality, liability, records and disputes survive. Effective {c.effectiveDate}.</p>}
  ]
};

const refunds: LegalDocument = {
  slug:"refunds",shortTitle:"Refunds",title:"Refund and cancellation policy",summary:"How subscriptions, cloud credit, downloads and marketplace purchases can be cancelled or refunded.",audience:"Consumers and business customers in the UK and Ireland",
  sections:[
    {id:"rights",title:"1. Statutory rights come first",content:<>{consumerSavings}<p>This policy adds to, and does not replace, mandatory rights. UK guidance is available from <External href="https://www.gov.uk/online-and-distance-selling-for-businesses/distance-selling">GOV.UK</External>; Irish guidance is available from the <External href="https://www.ccpc.ie/consumer-advice/consumer-rights/buying-goods/buying-online/">Competition and Consumer Protection Commission</External>.</p></>},
    {id:"cooling-off",title:"2. Fourteen-day cancellation period",content:<><p>If you are a UK or Irish consumer who buys a subscription or digital service online, you normally have 14 days from the day after the contract is concluded to cancel without giving a reason. Tell us by an unequivocal statement before the period ends. You may use the model form below, but do not have to.</p><p>If you expressly requested that a service begin during the cancellation period and then cancel, we may deduct only a proportionate amount for service actually supplied, where the law and checkout disclosures permit. If we did not provide required cancellation information, the period may be extended by up to 12 months.</p></>},
    {id:"calculation",title:"How the cancellation period is calculated",content:<><p>For a service or digital-service contract, the period begins when the contract is concluded. The cancellation is timely if the notice is sent before the period expires, even if we read it later. If the final day falls on a day when the chosen communication channel is unavailable, mandatory rules about time computation apply.</p><p>A free account without a paid or personal-data exchange beyond what is necessary to supply it may fall outside some consumer-contract provisions, but we will not use that distinction to obstruct account closure. A business purchase is assessed by purpose: an individual acting wholly or mainly outside a trade, business, craft or profession is a consumer.</p><p>The 14-day statutory period is distinct from a trial, satisfaction promise or renewal cancellation right. Where more than one applies, you receive the most favourable outcome required by law or expressly offered at checkout.</p></>},
    {id:"digital",title:"3. Downloads and digital content",content:<p>Downloading the desktop application does not by itself remove a statutory cancellation right. Where paid digital content is supplied immediately, the right is lost only if, before supply, you gave express consent to immediate performance, acknowledged that cancellation rights would be lost, and received the required confirmation. If that consent flow was not completed, we will not rely on the exception.</p>},
    {id:"nonconformity",title:"Faulty, misdescribed or unavailable supply",content:<><p>Cancellation for convenience is different from a remedy for breach. If digital content or a digital service is not supplied, is unsafe, materially misdescribed, lacks promised functionality or compatibility, is not of required quality or fitness, or is not kept in conformity by required updates, contact us with the affected version, date and evidence.</p><p>Depending on the applicable UK or Irish rule, remedies can include bringing the content or service into conformity within a reasonable time and without significant inconvenience, a price reduction, termination and refund, or compensation for qualifying damage to a device or other digital content. We will not require repeated repair attempts where the law permits an immediate reduction or termination.</p><p>A problem caused solely by unsupported customer equipment, an unauthorised modification, failure to install a clearly notified necessary update, or a third-party system outside the promised compatibility may not be our breach. We bear any burden of proof assigned to the trader by law.</p></>},
    {id:"subscription",title:"4. Subscriptions",content:<p>You may stop renewal by contacting us. Ordinary cancellation takes effect at the end of the current paid period. A timely statutory cancellation, a qualifying materially detrimental change, or a failure to supply a conforming service may entitle you to an earlier termination and refund. We do not charge a cancellation fee. Before UK subscription sales subject to the January 2027 regime, we must also provide the required easy online exit, reminders and renewal cooling-off process.</p>},
    {id:"credit",title:"5. Prepaid cloud credit",content:<p>Unused prepaid credit purchased directly from sndbox may be refunded during the statutory cancellation period. Credit already consumed by hosted runner, managed browser, storage or egress use requested during that period may be deducted where legally permitted. After the period, unused credit is normally non-refundable and non-transferable unless the service is discontinued, the charge was erroneous, or law requires otherwise. Credit does not expire unless a clearly disclosed checkout term lawfully says so.</p>},
    {id:"promotions",title:"Trials, promotions and referral credit",content:<p>Promotional or referral credit has no cash value and is not refunded unless mandatory law requires otherwise. If a qualifying payment is refunded below the referral threshold, associated referral rewards may be reversed from both accounts. We will not create a negative cash balance solely by reversing unused promotional credit; abuse, self-referral and coordinated cycles may be addressed under the stated referral rules and Acceptable Use Policy.</p>},
    {id:"marketplace",title:"6. Marketplace purchases",content:<p>The listing and receipt identify the seller. Send a cancellation or conformity request to the seller and to sndbox where we processed the payment. Independent publishers cannot exclude consumer rights. If a plugin is defective, unsafe, misdescribed, not supplied, or lacks required updates, statutory repair, replacement, price reduction, termination or refund remedies may apply.</p>},
    {id:"business",title:"7. Business customers",content:<p>The consumer cooling-off period does not apply to purchases wholly or mainly for business use. Business refunds follow the order form and these terms. We will correct duplicate, fraudulent or manifestly erroneous charges and may issue service credit for verified metering or availability failures.</p>},
    {id:"service-end",title:"Discontinuation and material changes",content:<p>If we permanently discontinue a prepaid paid service without providing a reasonably equivalent alternative, we will give reasonable notice and refund the unused portion of the affected subscription or purchased cloud credit. If a lawful unilateral modification materially and adversely affects an Irish consumer’s continuing digital service, we will provide advance information on a durable medium and any statutory right to terminate. This does not apply to a change made solely to maintain conformity, security or law without additional cost and without material adverse effect.</p>},
    {id:"process",title:"8. How refunds are paid",content:<p>Contact <Contact /> with the account email, order or receipt reference, purchase date, item, amount and reason. We may verify identity. Where a statutory cancellation refund is due, we pay it without undue delay and normally within 14 days after being informed, using the original payment method unless you agree otherwise, without a refund fee. Bank processing time is outside our control.</p>},
    {id:"refund-review",title:"Investigation, partial refunds and evidence",content:<><p>We may ask for information reasonably needed to locate a payment, confirm authority, distinguish consumed service from unused value, reproduce a defect or investigate fraud. We do not require technical proof a consumer could not reasonably provide. Any deduction or partial refund will be itemised by service period or metered use.</p><p>Taxes are refunded to the extent included in the refundable charge. Foreign-exchange differences and bank charges we did not impose are handled by the payment provider, without limiting a right to receive the amount legally due. We will explain a refusal and the available complaint route.</p><p>Starting a chargeback does not remove statutory rights, but duplicate recovery is not permitted. Please contact us first where practical so we can investigate quickly. We may provide transaction evidence to the payment provider and process chargeback data under the Privacy notice.</p></>},
    {id:"form",title:"9. Model cancellation form",content:<blockquote><p>To: <span className="legal-required">{c.legalName}, {c.registeredOffice}, {c.legalEmail}</span></p><p>I/We give notice that I/We cancel my/our contract for: [service or digital content].</p><p>Ordered on: [date]. Name: [name]. Address: [address]. Account email: [email]. Order reference: [reference].</p><p>Signature (only if sent on paper): __________ Date: __________</p></blockquote>},
    {id:"effective",title:"10. Contact",content:<p>Questions or complaints: <Contact />. Telephone: <span className="legal-required">{c.telephone}</span>. Effective {c.effectiveDate}.</p>}
  ]
};

const dpa: LegalDocument = {
  slug:"data-processing-addendum",shortTitle:"DPA",title:"Data Processing Addendum",summary:"Article 28 processor terms for Customer Personal Data handled by sndbox hosted services.",audience:"Customers using sndbox to process personal data",
  sections:[
    {id:"parties",title:"1. Parties and priority",content:<><p>This DPA forms part of the agreement between the customer (“Controller”) and <span className="legal-required">{c.legalName}</span> (“Processor”) when sndbox processes Customer Personal Data on the customer’s behalf. It applies automatically from the effective date of the service agreement.</p><p>“Data Protection Law” means the EU GDPR, UK GDPR, UK Data Protection Act 2018, Ireland Data Protection Act 2018 and other privacy law applicable to the processing. Terms such as controller, processor, personal data, processing and supervisory authority have their statutory meanings. This DPA controls over inconsistent service terms for data protection matters.</p></>},
    {id:"instructions",title:"2. Instructions and roles",content:<><p>Controller instructs Processor to process Customer Personal Data to provide, secure and support the selected hosted services, as configured by authorised users, and as further documented in Annex 1. Processor will process only on documented instructions, including for transfers, unless law requires otherwise; where permitted, Processor will notify Controller before legally required processing.</p><p>Controller is responsible for lawful instructions, transparency, legal bases, data accuracy and responding to data subjects. Processor will immediately tell Controller if it believes an instruction infringes Data Protection Law and may pause the affected processing.</p></>},
    {id:"instruction-scope",title:"Documented instruction channels",content:<><p>Documented instructions include the service agreement, this DPA, an Order, product configuration and actions submitted by authorised users through supported interfaces. Processor is not required to follow an instruction sent through an unauthorised channel or one that would alter the fundamental service without written agreement.</p><p>Where Controller enables a plugin, third-party connection, self-hosted runner, external webhook or chosen storage destination, that configuration is an instruction to transmit the selected data to that destination. Controller is responsible for the destination and its own contract with the recipient unless Processor has engaged it as a subprocessor.</p><p>Processor may aggregate or irreversibly anonymise service information so it is no longer personal data. Anonymisation must be assessed against reasonably likely means of re-identification; merely replacing an identifier is pseudonymisation, not anonymisation, and remains subject to this DPA.</p></>},
    {id:"people",title:"3. Confidentiality and personnel",content:<p>Processor ensures that personnel authorised to process Customer Personal Data are bound by confidentiality, receive appropriate training, and access data only as needed for their duties.</p>},
    {id:"security",title:"4. Security",content:<><p>Processor will implement and maintain appropriate technical and organisational measures under Article 32, taking account of risk, state of the art, costs and processing context. Measures are described in Annex 2. Controller remains responsible for secure workspace configuration, permissions, connections, runners and endpoints under its control.</p><p>Processor may update measures without materially reducing overall protection. On reasonable request, Processor will provide information needed to demonstrate compliance, subject to confidentiality and security restrictions.</p></>},
    {id:"security-governance",title:"Security governance and shared responsibility",content:<><p>Processor will maintain access authorisation, change control, vulnerability handling, incident response, backup and recovery, secure development and supplier-review processes proportionate to the Hosted Service. Production access must be individually attributable and reviewed. Support access to customer diagnostics is disabled by default, time-bounded, customer-approved by a separate person, restricted to aggregated diagnostics and recorded in an append-only history.</p><p>Controller must manage users and roles, require appropriate authentication, review plugin and workflow permissions, secure its endpoints and self-hosted runners, classify data, configure retention and avoid unsupported use. A failure in Controller-controlled credentials, code, destinations or third-party accounts is not a Processor security failure unless Processor contributed to it.</p> </>},
    {id:"subprocessors",title:"5. Subprocessors",content:<><p>Controller gives general written authorisation for the subprocessors on our <Link href="/legal/subprocessors">Subprocessors page</Link>. Processor will impose materially equivalent Article 28 obligations, remain responsible for subprocessor performance, and give at least 30 days’ notice before a new subprocessor processes Customer Personal Data.</p><p>Controller may object during that period on reasonable data-protection grounds. The parties will seek a practical alternative. If none is available, Controller may terminate the affected service without penalty and receive a pro-rata refund for the unused prepaid term. This is Controller’s sole remedy for the objection, without limiting mandatory law.</p></>},
    {id:"assistance",title:"6. Assistance",content:<p>Taking account of the nature of processing and information available, Processor will reasonably assist Controller with data-subject requests, security, breach notification, DPIAs and prior consultation. Processor will not respond directly to a request concerning Customer Personal Data unless authorised or legally required. Additional work outside standard functionality may be charged at agreed rates where law permits.</p>},
    {id:"requests",title:"Data-subject and authority requests",content:<><p>If Processor receives a data-subject request identifiable as concerning Controller’s Customer Personal Data, it will promptly redirect the requester to Controller and notify Controller where lawful. Processor will provide self-service search, export, correction, restriction or deletion functionality available in the service and reasonable further assistance needed because Controller cannot fulfil the request alone.</p><p>If Processor receives a binding demand from a public authority for Customer Personal Data, it will verify authority, challenge unlawful or disproportionate demands where reasonable, disclose the minimum required and notify Controller before disclosure unless prohibited. If notice is temporarily prohibited, Processor will seek permission to notify and do so when the prohibition ends.</p></>},
    {id:"breach",title:"7. Personal data breaches",content:<p>Processor will notify Controller without undue delay after becoming aware of a Personal Data Breach affecting Customer Personal Data, and provide available information reasonably needed for Controller’s Articles 33 and 34 duties. Notice is not an admission of fault. Processor will contain, investigate, mitigate and document the incident and provide material updates.</p>},
    {id:"breach-detail",title:"Breach-notice content",content:<p>To the extent known, notice will describe the nature of the breach; affected systems, data categories and approximate data-subject/record volumes; likely consequences; containment and mitigation; contact point; and information reasonably needed for notification. Processor may provide information in phases and will provide a final incident summary when appropriate. Controller is responsible for deciding whether and how to notify its supervisory authority and data subjects, with Processor’s reasonable assistance.</p>},
    {id:"return",title:"8. Return and deletion",content:<p>At the end of service, Processor will, at Controller’s choice, return or delete Customer Personal Data, unless law requires retention. Standard self-service export and deletion tools satisfy this obligation where available. Data in backups is isolated from ordinary use and deleted on the backup cycle. Security, audit, billing and deletion records that Processor holds as controller are governed by the Privacy notice.</p>},
    {id:"retention-dpa",title:"Retention and deletion verification",content:<><p>During the service, configured retention applies by data class. Expired execution payload references are deleted or made cryptographically inaccessible while a minimised outcome summary may remain. Active executions, queued work and unresolved incidents are not purged until their operational state permits. Controller should select the shortest period compatible with its purpose and legal duties.</p><p>On request following termination, Processor will confirm completion of standard deletion or describe the lawful basis and period for retained data. Deletion from active systems does not require immediate overwrite of every backup sector where backups are protected, unavailable for ordinary use and expire under a documented cycle.</p></>},
    {id:"audit",title:"9. Audit",content:<p>Processor will make available information reasonably necessary to demonstrate Article 28 compliance and allow an audit by Controller or an independent auditor no more than once annually, plus after a material incident, regulator request or where a further audit is reasonably necessary to meet Data Protection Law. Audits require reasonable notice, confidentiality, minimal disruption and no access to other customers’ data or security-sensitive systems. Current independent reports should be used first where available. Controller bears its costs unless the audit identifies a material Processor breach. Nothing here restricts a supervisory authority’s powers.</p>},
    {id:"transfer",title:"10. International transfers",content:<><p>Processor will not make a restricted transfer without a lawful mechanism. EEA transfers may rely on adequacy or the <External href="https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=celex:32021D0914">EU Standard Contractual Clauses (Decision 2021/914)</External>. UK transfers may rely on adequacy regulations, the <External href="https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/international-transfers/appropriate-safeguards/what-are-standard-data-protection-clauses-the-uk-idta-and-the-addendum/">UK IDTA or UK Addendum</External>. The parties will execute the applicable module, tables and annexes before a transfer that requires them; this draft does not pretend that uncompleted transfer clauses are operative.</p><p>Processor will support required transfer risk assessments and implement supplementary measures where necessary.</p></>},
    {id:"transfer-priority",title:"Transfer-clause operation",content:<><p>Where executed EU SCCs apply, they prevail over conflicting commercial terms. The Controller-to-Processor module normally applies to Controller exports and the Processor-to-Processor module may apply where Controller is itself a processor. Docking is permitted as stated in the SCCs. The competent supervisory authority and governing law must be completed using the exporter’s establishment and applicable module.</p><p>For UK restricted transfers using the Addendum, the mandatory clauses of the ICO-approved Addendum apply without modification except as they permit. The parties must complete the parties, selected SCC modules, appendix information and termination selection. The data importer must support an assessment of destination law and supplementary measures. Transfers must be suspended if the required protection cannot be maintained.</p></>},
    {id:"records",title:"Compliance records and regulatory cooperation",content:<p>Processor will keep records of processing required of it, cooperate with competent supervisory authorities, make personnel and relevant policies available for proportionate compliance enquiries, and notify Controller of a regulator enquiry specifically concerning Customer Personal Data where lawful. Each party is responsible for its own Article 30 records, representative or DPO appointment, registration or fee, and regulator communications.</p>},
    {id:"dpa-liability",title:"Liability and changes",content:<><p>Liability arising under this DPA is subject to the agreement’s liability provisions except to the extent applicable Data Protection Law prohibits that limitation or grants data subjects direct rights. Nothing in the DPA relieves either party of its own statutory responsibility or prevents a data subject or regulator exercising a legal remedy.</p><p>We may update this DPA to reflect a change in law or service without materially reducing protection. Material changes receive advance notice where reasonably possible. If a change is required to comply with law, the parties will cooperate in good faith; Controller may terminate the affected processing if compliance cannot be achieved.</p></>},
    {id:"annex1",title:"Annex 1 — Processing details",content:<div className="legal-table-wrap"><table><tbody><tr><th>Subject matter</th><td>Hosted storage, synchronisation, scheduling, execution, browser automation, artifacts, integrations, support and security for Customer-configured workflows.</td></tr><tr><th>Duration</th><td>The service term plus configured retention, backup expiry and legally required retention.</td></tr><tr><th>Nature and purpose</th><td>Collection, recording, organisation, storage, retrieval, consultation, use, transmission, encryption, restriction and deletion solely to provide and secure the service.</td></tr><tr><th>Data subjects</th><td>Controller’s users, staff, customers, suppliers and other people whose data Controller submits or accesses through an automation.</td></tr><tr><th>Data types</th><td>Identity and contact data; account and authorisation data; workflow inputs/outputs; messages, documents and files; online identifiers; usage, logs and artifacts. Exact content is determined by Controller.</td></tr><tr><th>Sensitive data</th><td>Not intentionally required. Controller may submit special-category or criminal-offence data only where lawful and with appropriate safeguards; high-risk use may require a separate written agreement.</td></tr><tr><th>Frequency</th><td>Continuous or as initiated/scheduled by Controller.</td></tr></tbody></table></div>},
    {id:"annex2",title:"Annex 2 — Security measures",content:<ul><li>Encryption in transit and encryption of protected hosted values and key envelopes at rest.</li><li>Role- and permission-based access, least privilege, strong authentication and time-bounded customer-approved support diagnostics.</li><li>OS credential vaults for local secrets; secret-field redaction from logs and exports.</li><li>Signed, expiring runner commands; separated identities; auditable administrative and execution events.</li><li>Isolated managed-browser workloads, restricted network targets, download scanning and destruction of temporary profiles.</li><li>Signed, immutable, capability-declared plugin packages with automated and human review.</li><li>Retention controls, cryptographic erasure, deletion receipts, backup controls, incident response and recovery testing.</li><li>Vulnerability management, dependency and release integrity controls, monitoring and business-continuity measures appropriate to production deployment.</li></ul>},
    {id:"annex3",title:"Annex 3 — Contact and signature",content:<p>Controller details are those in its account or order form. Processor: <span className="legal-required">{c.legalName}, {c.registeredOffice}, {c.privacyEmail}</span>. The parties accept this DPA when entering the service agreement. Effective {c.effectiveDate}.</p>}
  ]
};

const subprocessors: LegalDocument = {
  slug:"subprocessors",shortTitle:"Subprocessors",title:"Subprocessors",summary:"Providers that may process Customer Personal Data for sndbox hosted services.",audience:"Customers and privacy reviewers",
  sections:[
    {id:"status",title:"Publication status",content:<aside className="legal-critical"><strong>Production deployment details required</strong><p>The code confirms the functions below, but the selected production vendors and processing locations are not present in this repository. This page must be completed from signed vendor contracts and the live infrastructure inventory before hosted processing begins. It must not be represented as a complete subprocessor list until then.</p></aside>},
    {id:"list",title:"Current service-provider register",content:<div className="legal-table-wrap"><table><thead><tr><th>Provider</th><th>Purpose</th><th>Data</th><th>Location / safeguard</th><th>Status</th></tr></thead><tbody><tr><td>Stripe group entity stated in the production Stripe agreement</td><td>Checkout, subscription and payment processing</td><td>Account, customer, transaction and billing identifiers; card data is supplied directly to Stripe</td><td>[Required from contract and account configuration]</td><td>Provider confirmed in code; role must be assessed per processing activity</td></tr><tr><td>[Production hosting provider]</td><td>Web, API, database and compute hosting</td><td>Account, workspace, operational and Customer Personal Data</td><td>[Required]</td><td>Not configured in repository</td></tr><tr><td>[Object storage provider]</td><td>Plugin packages, artifacts and protected payload storage</td><td>Customer Content, package and object metadata</td><td>[Required]</td><td>Not configured in repository</td></tr><tr><td>[OIDC identity provider]</td><td>Authentication and account identity</td><td>Name, email, identity subject and authentication events</td><td>[Required]</td><td>Vendor is deployment-configurable</td></tr><tr><td>[Transactional email provider]</td><td>Account, security, billing and support email</td><td>Email address and message content</td><td>[Required]</td><td>Vendor is deployment-configurable</td></tr><tr><td>[Observability provider, if any]</td><td>Service metrics and diagnostics</td><td>Minimised operational metadata</td><td>[Required]</td><td>Exporter is deployment-configurable</td></tr><tr><td>[Package scanning provider]</td><td>Malware and package review</td><td>Publisher packages and metadata</td><td>[Required]</td><td>Vendor is deployment-configurable</td></tr></tbody></table></div>},
    {id:"register-fields",title:"What the final register must disclose",content:<p>For each subprocessor, the production register must state the exact contracting provider entity, service and processing purpose, personal-data categories, data-subject categories, primary hosting and support-access countries, appointment date, transfer mechanism, and a link to relevant security/privacy information. A parent brand alone is insufficient where a different group entity signs the processing contract.</p>},
    {id:"diligence",title:"Selection and oversight",content:<><p>Before appointment, sndbox will assess the provider’s security, confidentiality, resilience, deletion, breach, audit, government-request and international-transfer controls in light of the data and service risk. The contract must impose the Article 28 obligations applicable to the processing and require approval for onward subprocessors.</p><p>Risk review is repeated on material service change, incident, control failure or contract renewal. Relevant assurance may include independent audit reports, penetration-test summaries, certifications, architecture evidence and contractual commitments; a certification is evidence, not a substitute for assessment.</p><p>Access must be least-privilege and restricted to the contracted purpose. sndbox remains responsible to the customer for an authorised subprocessor’s performance to the extent required by the DPA and law.</p></>},
    {id:"not-sub",title:"Providers that may not be subprocessors",content:<p>Customer-selected integrations and self-hosted runners normally act under the customer’s direct instruction and are not engaged by sndbox as subprocessors. Payment providers may act as independent controllers for fraud, compliance and payment-network purposes. The final register must classify each relationship from the actual contract and processing, not from labels alone.</p>},
    {id:"locations",title:"Locations and transfers",content:<p>A provider’s headquarters is not necessarily where data is stored or remotely accessed. The final assessment must cover primary and backup regions, support and engineering access, onward-provider locations and disaster-recovery movement. A transfer outside the UK or EEA will use an applicable adequacy decision/regulation or completed safeguards and transfer assessment described in the DPA.</p>},
    {id:"changes",title:"Change notices",content:<p>Customers subscribed to subprocessor notices will receive at least 30 days’ advance notice of a new subprocessor that will process Customer Personal Data, except an urgent replacement needed for security or legal compliance. Objections are handled under the <Link href="/legal/data-processing-addendum#subprocessors">DPA</Link>. Last reviewed {c.effectiveDate}. Contact <Contact kind="privacy" />.</p>},
    {id:"objections",title:"How to object",content:<p>Send the notice identifier, affected workspace and specific data-protection grounds before the stated appointment date. We will assess the risk, relevant safeguards and feasible alternatives such as disabling the affected feature or using another provider. An objection is not valid merely because a provider competes with the customer or is located in a country already covered by an adequate lawful mechanism, but we will consider documented security, legal and rights risks. If no reasonable solution exists, the termination remedy in the DPA applies.</p>}
  ]
};

const vulnerability: LegalDocument = {
  slug:"vulnerability-disclosure",shortTitle:"Security reports",title:"Vulnerability Disclosure Policy",summary:"How to report security vulnerabilities and the boundaries of good-faith research.",audience:"Security researchers and customers",
  sections:[
    {id:"report",title:"1. Report privately",content:<><p>Email <Contact kind="security" /> with the affected URL, version or component; clear reproduction steps; impact; relevant logs or screenshots with secrets removed; and a safe contact method. Do not use public issues or marketplace reviews for an unremediated vulnerability.</p><p>We aim to acknowledge a valid report within 3 business days, provide a triage update within 10 business days, and keep the reporter informed. These are targets, not service levels or a promise of a reward.</p></>},
    {id:"scope",title:"Systems in and out of scope",content:<div className="legal-table-wrap"><table><thead><tr><th>In scope</th><th>Out of scope unless separately authorised</th></tr></thead><tbody><tr><td>sndbox.app, app.sndbox.app, api.sndbox.app and identity.sndbox.app where operated by sndbox</td><td>Third-party identity, payment, hosting, email and connected-service infrastructure</td></tr><tr><td>Current supported sndbox desktop releases and official first-party plugins</td><td>Community plugins, forks, abandoned builds and modified binaries</td></tr><tr><td>Hosted runner, managed browser, marketplace and public API boundaries operated by sndbox</td><td>Customer devices, self-hosted runners, private networks, workflows and data</td></tr></tbody></table><p>If ownership is unclear, ask before testing. A hostname alone does not authorise testing a third-party service behind it.</p></div>},
    {id:"safe",title:"2. Good-faith research",content:<><p>If you make a good-faith effort to follow this policy, avoid privacy violations and disruption, and report promptly, we will not initiate legal action against you solely for accidental, proportionate violations necessary to demonstrate the vulnerability. This does not authorise activity prohibited by third parties or protect conduct outside our ability to authorise.</p><p>Stop and report immediately if you encounter personal data, Customer Content, credentials or destructive access. Delete data securely after we confirm receipt, unless law requires preservation.</p></>},
    {id:"allowed",title:"3. Permitted testing",content:<ul><li>Use accounts, workspaces, plugins, runners and data you own or have explicit permission to test.</li><li>Use the minimum requests and data needed to demonstrate impact.</li><li>Test only sndbox systems expressly in scope: public sndbox domains and current supported desktop releases.</li><li>Give us a reasonable remediation period before coordinated disclosure.</li></ul>},
    {id:"methods",title:"Testing method",content:<><p>Create test data and identify research traffic where practical. Prefer a non-destructive proof over exploitation. For access-control issues, demonstrate that an unauthorised object can be referenced without opening its contents. For command, browser or plugin escapes, stop once the boundary crossing is proven. Do not pivot, establish persistence or retrieve secrets.</p><p>Rate-limit automation and respect a request to pause while we protect users. Keep a timestamped record of requests and responses sufficient for reproduction. Encrypt sensitive reports in transit using a published key if available; the production security contact must publish a supported secure channel before launch.</p></>},
    {id:"excluded",title:"4. Not permitted",content:<ul><li>Denial of service, load testing, spam, social engineering, phishing or physical attacks.</li><li>Accessing, changing, downloading or retaining another person’s data.</li><li>Persistence, lateral movement, credential use beyond proof, malware, extortion or supply-chain interference.</li><li>Automated scanning that degrades service or violates a third party’s terms.</li><li>Testing third-party integrations, websites, open-source projects or customer infrastructure without their permission.</li></ul>},
    {id:"not-vulnerabilities",title:"Reports generally not eligible for security treatment",content:<ul><li>Missing best-practice headers without a demonstrated security impact.</li><li>Self-XSS, clickjacking on a page with no sensitive action, or logout CSRF without material effect.</li><li>Rate-limit observations that do not permit abuse, and version/banner disclosure without an exploit path.</li><li>Issues requiring a rooted device, compromised administrator, unsupported version or prior control of the victim’s account, unless they cross a distinct promised boundary.</li><li>Automated scanner output without validation, leaked credentials not belonging to sndbox, or social-engineering reports.</li></ul>},
    {id:"handling",title:"5. Our handling and disclosure",content:<p>We validate, prioritise and remediate according to risk. We may ask for clarification or coordinate an advisory and credit. Do not disclose before an agreed date or while users remain at unreasonable risk. Nothing here creates confidentiality obligations unless separately agreed, and we cannot accept trade secrets or information you are not allowed to share.</p>},
    {id:"triage",title:"Triage and remediation",content:<><p>We assess exploitability, privileges required, affected users, confidentiality/integrity/availability impact, detectability and available mitigations. A duplicate may be linked to the first complete report. We may close an issue that cannot be reproduced, is outside scope or has no material security impact, and will explain where safe.</p><p>Critical issues can require immediate containment, feature suspension, key rotation or signed revocation before a complete fix. Remediation timing depends on severity and ecosystem coordination. We will test the fix, assess variants and decide whether customers, regulators or the public require notice.</p></>},
    {id:"recognition",title:"Recognition and rewards",content:<p>There is no standing bug-bounty promise in this repository. Any payment is discretionary and must be agreed in writing; duplicate, ineligible or policy-violating reports may receive none. With permission, we may credit the reporter after remediation. We will not identify a reporter without consent unless law requires it.</p>},
    {id:"other",title:"6. Other security matters",content:<p>Lost credentials, account compromise, abuse and privacy incidents should also be reported promptly, clearly labelled. For immediate danger contact emergency services. Effective {c.effectiveDate}.</p>}
  ]
};

const accessibility: LegalDocument = {
  slug:"accessibility",shortTitle:"Accessibility",title:"Accessibility statement",summary:"Our accessibility target, current known limitations, feedback route and legal context.",audience:"Website, account portal and desktop application users",
  sections:[
    {id:"commitment",title:"1. Commitment and standard",content:<><p>We want people with disabilities to be able to use sndbox independently. Our target is <External href="https://www.w3.org/TR/WCAG22/">Web Content Accessibility Guidelines (WCAG) 2.2 Level AA</External> for the marketing site, account portal and core desktop workflows. Accessibility is considered in keyboard operation, screen-reader semantics, focus visibility, contrast, reduced motion, error handling and alternatives to pointer-only graph editing.</p><p>This statement is a candid description, not a certification. No independent accessibility audit is present in this repository.</p></>},
    {id:"scope",title:"Products and content in scope",content:<><p>This statement covers the public marketing website at sndbox.app, authenticated portal at app.sndbox.app, official documentation at docs.sndbox.app, current supported desktop application and first-party interface components. It covers account creation, billing, marketplace browsing, workflow editing, settings and execution inspection to the extent those surfaces are currently available.</p><p>It does not certify third-party websites automated by a customer, third-party identity or payment pages, community plugin interfaces, customer-created workflows and output, or self-hosted administration outside sndbox software. We still seek accessible integration points, identify known barriers and provide reasonable support where we can influence the experience.</p></>},
    {id:"works",title:"2. What is built in",content:<ul><li>Skip links, semantic landmarks, labelled navigation and visible keyboard focus.</li><li>Reduced-motion support and user controls for density, contrast and motion in the desktop app.</li><li>A keyboard- and screen-reader-operable workflow editor providing node selection, movement, connection and deletion without drag gestures.</li><li>Textual status, validation and error messages that do not rely on colour alone.</li><li>Labelled forms and controls, responsive layouts and contextual names for icon-only actions.</li></ul>},
    {id:"expected-use",title:"Expected ways to use the service",content:<ul><li>Navigate headings, landmarks, links and controls with a keyboard without a pointer.</li><li>Zoom browser content to at least 200% and use narrow reflow layouts without losing core information or controls.</li><li>Use modern screen readers with semantic names, roles, states and live status announcements.</li><li>Enable increased contrast, reduced motion and density preferences without changing account functionality.</li><li>Use the accessible graph editor instead of dragging nodes or connections on the visual canvas.</li><li>Request legal, support and product information in a reasonable alternative format.</li></ul>},
    {id:"limits",title:"3. Known limitations",content:<ul><li>The visual node canvas is complex; the companion accessible editor is the supported non-drag alternative, but needs external screen-reader testing.</li><li>Some third-party plugin content, connected websites, documents and marketplace assets are outside our direct control.</li><li>Generated workflow output may be inaccessible depending on customer configuration.</li><li>Formal automated testing, manual screen-reader verification and an independent WCAG audit remain launch gates.</li><li>macOS and Linux builds are not currently available in this source state, so platform accessibility has not been verified.</li></ul>},
    {id:"compatibility",title:"Compatibility assumptions",content:<p>Testing should cover current stable versions of Chrome, Edge and Firefox on Windows; Safari on macOS where a build is offered; Windows screen readers including NVDA and Narrator; VoiceOver where supported; keyboard-only operation; browser zoom; high-contrast modes; and reduced-motion preferences. Older browsers, unsupported operating systems and unusual browser/assistive-technology combinations may behave differently. The final statement must replace these planned combinations with the versions actually tested.</p>},
    {id:"help",title:"4. Feedback and alternative formats",content:<p>If anything prevents access, contact <Contact kind="accessibility" /> and tell us the page or feature, assistive technology and preferred response format. You do not need to disclose a diagnosis. We aim to acknowledge within 3 business days and provide a substantive response or reasonable-adjustment plan within 15 business days. We can provide information in an accessible alternative format where reasonable.</p>},
    {id:"response",title:"How we handle an accessibility request",content:<><p>We log the barrier, assess severity and affected task, reproduce it where possible, offer a workaround or alternative format, assign an owner and track remediation. Urgent barriers to authentication, purchase, cancellation, privacy rights or core workflow control receive priority. We will explain if a requested adjustment is not technically possible or would impose a disproportionate burden and look for an effective alternative.</p><p>Accessibility feedback is not used to infer a medical diagnosis. We keep only the information needed to respond and improve the service under the Privacy notice. Requests may be made by a representative with appropriate authority.</p></>},
    {id:"law",title:"5. Legal context",content:<><p>UK service providers have duties to make reasonable adjustments under the <External href="https://www.legislation.gov.uk/ukpga/2010/15/contents">Equality Act 2010</External>; Northern Ireland uses the <External href="https://www.legislation.gov.uk/ukpga/1995/50/contents">Disability Discrimination Act 1995</External>. For covered services offered in Ireland, the <External href="https://www.irishstatutebook.ie/eli/2023/si/636/made/en/print">European Union (Accessibility Requirements of Products and Services) Regulations 2023</External> have applied since 28 June 2025, subject to their scope and exemptions.</p><p>The operator must assess whether sndbox is a covered e-commerce service, whether any microenterprise exemption applies, and complete the service information required by Schedule 3 before relying on this statement for Irish EAA compliance.</p></>},
    {id:"eaa-information",title:"Irish accessibility service information",content:<><p>If the Irish Accessibility Regulations apply, the final service information must explain in accessible form how the service meets applicable requirements, describe the service and its operation, identify the standards or technical specifications used, and describe the conformity-assessment procedure. It must remain available while the service operates and be updated when the service changes.</p><p>The Regulations’ service requirements include accessible information, websites and mobile services that are perceivable, operable, understandable and robust, and accessible identification, security, payment and support functions where applicable. Invoking a microenterprise or disproportionate-burden exception requires a documented legal assessment; it is not assumed here.</p></>},
    {id:"assessment",title:"Assessment method and status",content:<p>The repository contains component tests and an internal WCAG 2.2 AA review for key criteria. That evidence must be supplemented before publication by automated scans across representative pages, keyboard task testing, 200%/400% zoom and reflow review, colour and non-text contrast checks, error-recovery testing, screen-reader testing of complete user journeys, and review of downloadable documents and third-party checkout/authentication handoffs. Defects must be risk-ranked and regressions treated as release blockers.</p>},
    {id:"review",title:"6. Preparation and review",content:<p>Prepared {c.effectiveDate}. Review after any material interface change and at least annually. Owner: <span className="legal-required">{c.legalName}</span>.</p>}
  ]
};

const complaints: LegalDocument = {
  slug:"complaints",shortTitle:"Complaints",title:"Complaints and content notices",summary:"How to raise service, consumer, privacy, accessibility, marketplace and illegal-content complaints.",audience:"Customers, marketplace users, rights holders and affected people",
  sections:[
    {id:"contact",title:"1. Start here",content:<><p>Send your complaint through our <Link href="/contact">contact form</Link> or to <Contact />. Include your name and contact details, account or workspace if relevant, order/reference number, what happened, the outcome you want and supporting evidence. Do not send passwords, secret keys or unlawful material.</p><p>We aim to acknowledge within 3 business days and give a final response within 15 business days. Complex, safety or multi-party cases may take longer; we will explain why and provide updates.</p></>},
    {id:"principles",title:"How we assess complaints",content:<><p>We act fairly, consistently and proportionately. The reviewer will identify the issues, preserve relevant evidence, check the applicable contract and law, seek information from affected parties where appropriate, manage conflicts of interest, and record reasons. A person materially involved in the underlying decision should not conduct the final appeal where separation is reasonably possible.</p><p>Possible outcomes include explanation, correction, restored access, content restriction or reinstatement, security remediation, billing adjustment, refund, apology, policy or product change, or no action with reasons. We will not disclose another person’s confidential information merely to explain an outcome.</p><p>Urgent risks to life, child safety, account security or continuing unlawful disclosure are triaged before ordinary target times. A complaint does not automatically pause a charge, workflow or moderation decision; request an interim measure and explain the risk.</p></>},
    {id:"routes",title:"2. Specialist routes",content:<ul><li><strong>Billing, cancellation or refunds:</strong> see the <Link href="/legal/refunds">Refund and cancellation policy</Link>.</li><li><strong>Personal data:</strong> contact <Contact kind="privacy" />. You may also complain directly to the ICO, Irish DPC or another competent authority.</li><li><strong>Accessibility:</strong> contact <Contact kind="accessibility" /> and see the <Link href="/legal/accessibility">Accessibility statement</Link>.</li><li><strong>Security vulnerabilities:</strong> report privately under the <Link href="/legal/vulnerability-disclosure">Vulnerability Disclosure Policy</Link>.</li><li><strong>Plugin support:</strong> contact the publisher shown on the listing, and copy sndbox if the marketplace or purchase is involved.</li></ul>},
    {id:"data-complaints",title:"Data-protection complaints",content:<><p>A complaint that sndbox infringed the UK GDPR or Part 3 of the Data Protection Act 2018 may be submitted electronically through <Link href="/contact?type=privacy">our privacy route</Link>. Under section 164A, in force from 19 June 2026, we must facilitate complaints, acknowledge receipt within 30 days, make appropriate enquiries, keep the complainant informed of progress and communicate the outcome without undue delay. Our shorter service targets remain goals.</p><p>For Irish/EU GDPR complaints, we similarly investigate and respond transparently. Rights requests such as access or erasure are handled under their separate statutory time limits even when included in a complaint. We will identify which part of a message is a complaint and which part is a rights request.</p><p>A final response will identify the issue considered, enquiries made to an appropriate extent, outcome, remedial action and right to approach the competent supervisory authority. You may approach the authority at any time.</p></>},
    {id:"illegal-content",title:"3. Illegal content and intellectual-property notices",content:<><p>Identify the exact URL, plugin, version or content; give a sufficiently substantiated explanation of why it is illegal or infringes your rights; state your name and email (unless an applicable exception permits omission); and confirm your good-faith belief that the information is accurate. For copyright or trade-mark claims, identify the protected work/right and your authority to act.</p><p>We will acknowledge receipt and make a timely, diligent and objective decision. We may preserve evidence, restrict content, request more information, notify the publisher, or refer credible threats to authorities. Do not send child sexual abuse material or other unlawful content; provide the location only and report it to the appropriate authority.</p></>},
    {id:"notice-action",title:"Digital Services Act notice and action",content:<><p>For a notice under Article 16 of the DSA, provide: the reasons you allege the information is illegal; the exact electronic location, including URL and any additional identifier; your name and email except for qualifying sexual-abuse offences; and a statement confirming a good-faith belief that the information and allegations are accurate and complete.</p><p>A sufficiently precise and substantiated notice can give us awareness requiring timely action. We will acknowledge it electronically, decide diligently and without arbitrary discrimination, and communicate the decision and redress options. If we restrict publisher content, the statement of reasons should identify the facts, territorial scope, duration, legal or contractual ground, use of automation and appeal routes, subject to lawful exceptions.</p><p>Reports of content presenting an imminent threat should be clearly marked urgent. We may notify law-enforcement or judicial authorities where the DSA or other law requires suspicion of a criminal offence involving a threat to life or safety.</p></>},
    {id:"moderation-appeal",title:"4. Marketplace moderation appeals",content:<p>A publisher or affected user may appeal a listing restriction, content decision, account suspension or notice decision within six months, or any longer statutory period. Explain the error and supply relevant evidence. A suitably qualified person not responsible for the original decision will review the appeal where required. Repeatedly submitting manifestly unfounded notices or illegal content may result in proportionate suspension after warning.</p>},
    {id:"appeal-detail",title:"Appeal review",content:<p>An appeal may challenge factual error, legal characterisation, identity, proportionality, territorial scope, duration or inconsistent policy application. We may ask the original decision-maker or affected publisher for information but the appeal receives meaningful human supervision. We will reverse or vary an unsupported decision and explain the result. DSA recipients may also use a certified out-of-court dispute-settlement body; participation does not remove court rights.</p>},
    {id:"external",title:"5. External escalation",content:<><p>UK consumers can seek advice from Citizens Advice or Consumerline in Northern Ireland and may use any competent approved alternative-dispute-resolution body where applicable. Irish consumers can contact the <External href="https://www.ccpc.ie/consumer-advice/how-to-complain/">CCPC</External>. We will identify any ADR entity we are obliged or agree to use in the final response.</p><p>For Digital Services Act issues, recipients may contact their Digital Services Coordinator; in Ireland this is <External href="https://www.cnam.ie/general-public/report-complain/something-i-saw-or-experienced-online/">Coimisiún na Meán</External>. Eligible EU users may also choose a certified out-of-court dispute-settlement body. Court rights are unaffected.</p></>},
    {id:"records",title:"Records, confidentiality and misuse",content:<><p>Complaint records are access-controlled and retained according to their subject: consumer, moderation, security, privacy, billing or legal-claim schedules. We share them only with people needed to investigate, affected parties where fairness requires, providers assisting the case, advisers and authorities with a lawful basis. The Privacy notice applies.</p><p>We protect good-faith complainants from retaliation. Knowingly false allegations, harassment, duplicate flooding or repeated manifestly unfounded notices can be restricted after warning and a case-specific assessment. Anonymous information may still be investigated, but lack of contact or evidence can limit the response.</p></>},
    {id:"record",title:"6. Fairness and records",content:<p>We do not retaliate for good-faith complaints. We use complaint data to investigate, respond, prevent abuse and meet legal duties under the <Link href="/legal/privacy">Privacy notice</Link>. Effective {c.effectiveDate}.</p>}
  ]
};

